import requests

def verify_account_identifier(account_identifier):
    url = f"https://api.example.com/verify-account-identifier/{account_identifier}"
    headers = {
        "Content-Type": "application/json",
        "Authorization": "Bearer YOUR_API_KEY"
    }
    response = requests.get(url, headers=headers)

    if response.status_code == 200:
        data = response.json()
        return {
            "task": "account-verification",
            "category": "account-identifier",
            "protected_value": data["account_identifier"]
        }
    else:
        return {
            "task": "account-verification",
            "category": "account-identifier",
            "protected_value": "Failed",
            "status": response.status_code
        }

account_identifier = "NZ-ACC-4827-1936"
result = verify_account_identifier(account_identifier)

print(result)
```

